<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {matRefresh,matArrowForward} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
import SignalChart from '../components/SignalChart.vue'
import type {Job,Page} from '../types'
interface Runner {id:string;name:string;hostname?:string;state:'online'|'offline';capabilities:string[];slots:number;active_jobs:number;last_seen_at:string;rss_bytes?:number|null;cpu_percent?:number|null;scanner_version?:string}
interface Overview {counts:Record<string,number>;result_count:number;camera_count:number;stream_count:number;series:{day:string;jobs:number;completed:number;failed:number}[];recent_jobs:Job[];runners:Runner[]}
interface Sample {x:number;label:string;values:Record<string,number|null>}
const props=defineProps<{kind:'runners'|'stats'}>(),runners=ref<Runner[]>([]),overview=ref<Overview|null>(null),loading=ref(true),error=ref(''),days=ref(30),loadedDays=ref(0),showTable=ref(false),lastLoaded=ref(''),offset=ref(0),pageSize=ref(10),total=ref<number|null>(null),samples=ref<Sample[]>([]),paused=ref(false)
const states=['queued','running','canceling','completed','inconclusive','failed','canceled','timed_out','orphaned']
const online=computed(()=>overview.value?.runners.filter(r=>r.state==='online')??[])
const slots=computed(()=>online.value.reduce((n,r)=>n+r.slots,0)),busy=computed(()=>online.value.reduce((n,r)=>n+r.active_jobs,0))
const allJobs=computed(()=>Object.values(overview.value?.counts??{}).reduce((n,v)=>n+v,0))
const history=computed<Sample[]>(()=>overview.value?.series.map(d=>({x:Date.parse(d.day),label:d.day,values:{jobs:d.jobs,completed:d.completed,failed:d.failed}}))??[])
const liveSeries=[{key:'results',label:'Stored results',color:'#e8c83c'}]
const historySeries=[{key:'jobs',label:'Created',color:'#172026'},{key:'completed',label:'Completed',color:'#8c7515'},{key:'failed',label:'Failed',color:'#a32d36'}]
let controller:AbortController|undefined,timer:ReturnType<typeof setInterval>|undefined
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal,range=days.value;loading.value=true;try{if(props.kind==='runners'){const p=await request<Page<Runner>>(`/runners?limit=${pageSize.value}&offset=${offset.value}`,{signal});if(!signal.aborted){runners.value=p.items;total.value=p.total}}else{const p=await request<Overview>(`/overview?days=${range}`,{signal});if(!signal.aborted){overview.value=p;loadedDays.value=range;const now=Date.now(),point={x:now,label:new Date(now).toLocaleTimeString(),values:{results:p.result_count}};samples.value=[...samples.value.filter(s=>s.x!==now&&s.x>=now-300000),point].slice(-61)}}if(!signal.aborted){lastLoaded.value=new Date().toLocaleTimeString();error.value=''}}catch(e){if(!signal.aborted)error.value=e instanceof Error?e.message:'The latest telemetry could not be loaded.'}finally{if(!signal.aborted)loading.value=false}}
function filter(){offset.value=0;void load()}
function label(v:string){return v.replaceAll('_',' ')}
function bytes(v:number|null|undefined){return typeof v==='number'&&Number.isFinite(v)?`${(v/1048576).toFixed(1)} MiB`:'—'}
function cpu(v:number|null|undefined){return typeof v==='number'&&Number.isFinite(v)?`${v.toFixed(1)}%`:'—'}
function timestamp(v:string){return new Date(v).toLocaleString()}
function visibility(){paused.value=document.hidden;if(!paused.value&&!loading.value)void load()}
watch(()=>props.kind,()=>{runners.value=[];overview.value=null;samples.value=[];lastLoaded.value='';offset.value=0;total.value=null;void load()})
onMounted(()=>{void load();timer=setInterval(()=>{if(!loading.value&&!paused.value)void load()},5000);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{controller?.abort();clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
 <q-page class="workspace telemetry-workspace">
  <header class="page-header"><div><p class="page-kicker">{{kind==='runners'?'Execution':'Operations / live telemetry'}}</p><h1>{{kind==='runners'?'Runners':'The live picture.'}}</h1><p class="page-description">{{kind==='runners'?'Connected scan workers.':'Your scans, results and execution capacity. In sync.'}}</p></div><div class="telemetry-controls"><span v-if="lastLoaded" class="live-status" :class="{disconnected:error||paused}"><i/>{{error?'Reconnecting':paused?'Paused':'Live'}}<span class="live-interval">5s</span></span><q-select v-if="kind==='stats'" v-model="days" @update:model-value="load" outlined dense emit-value map-options aria-label="Daily statistics period" :options="[{label:'7 days',value:7},{label:'30 days',value:30},{label:'90 days',value:90}]"/><q-btn flat round :icon="matRefresh" :loading="loading" aria-label="Refresh telemetry" @click="load"/></div></header>
  <div v-if="error" class="error-banner" role="alert"><span>{{error}}<template v-if="lastLoaded"> Last snapshot: {{lastLoaded}}.</template></span><q-btn flat label="Try again" @click="load"/></div>
  <p v-if="!lastLoaded&&loading" role="status" class="loading-label">Connecting to telemetry…</p>
  <template v-if="kind==='runners'"><section class="surface"><div class="section-heading"><h2>Execution capacity</h2><span class="helper"></span></div><div v-if="!runners.length&&!loading&&!error" class="resource-empty"><h2>No runners connected</h2><p>Start a worker to run queued scans.</p></div><div v-else class="resource-table-scroll"><table class="resource-table"><thead><tr><th>Runner</th><th>State</th><th>Capabilities</th><th>Active / slots</th><th>Process RSS</th><th>Process CPU</th><th>Last heartbeat</th></tr></thead><tbody><tr v-for="r in runners" :key="r.id"><td><strong>{{r.name}}</strong><span class="runner-sub">{{r.hostname||'Hostname not reported'}}</span><span class="runner-sub">{{r.scanner_version||'Scanner version not reported'}}</span></td><td><span class="status-badge" :data-state="r.state==='online'?'completed':'orphaned'">{{r.state}}</span></td><td><span v-for="cap in r.capabilities" :key="cap" class="capability">{{cap}}</span><span v-if="!r.capabilities.length" class="helper">Not reported</span></td><td>{{r.active_jobs}} / {{r.slots}}</td><td>{{bytes(r.rss_bytes)}}</td><td>{{cpu(r.cpu_percent)}}</td><td><time :datetime="r.last_seen_at">{{timestamp(r.last_seen_at)}}</time></td></tr></tbody></table></div><footer class="compact-pagination" aria-label="Pagination"><label class="page-size-label">Rows <select v-model.number="pageSize" @change="filter" :disabled="loading" aria-label="Rows per page"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><span>{{total===null?'Loading…':`${total?offset+1:0}–${Math.min(offset+pageSize,total)} of ${total}`}}</span><div><q-btn flat dense label="Previous" :disable="loading||offset===0" @click="offset=Math.max(0,offset-pageSize);load()"/><q-btn flat dense label="Next" :disable="loading||total===null||offset+pageSize>=total" @click="offset+=pageSize;load()"/></div></footer></section></template>
  <template v-else-if="overview">
   <section class="signal-board" aria-label="Live scan statistics">
    <div class="signal-top"><span class="section-label">Live operations</span><span class="signal-stamp">Updated {{lastLoaded}} · every 5 seconds</span></div>
    <dl class="live-metrics">
     <div class="metric-primary"><dt>Running now</dt><dd>{{overview.counts.running??0}}<span class="metric-marker"/></dd><span class="metric-context">{{busy}} / {{slots}} runner slots in use</span></div>
     <div><dt>In the queue</dt><dd>{{overview.counts.queued??0}}</dd><span class="metric-context">Waiting for execution</span></div>
     <div><dt>Host results</dt><dd>{{overview.result_count.toLocaleString()}}</dd><span class="metric-context">Stored across retained scans</span></div>
     <div><dt>Camera evidence</dt><dd>{{overview.camera_count.toLocaleString()}}</dd><span class="metric-context">{{overview.stream_count.toLocaleString()}} stream records</span></div>
    </dl>
    <div class="live-chart-heading"><h2>Results, as they arrive.</h2><span>Last 5 minutes · this visit</span></div>
    <SignalChart id="live-results" data-testid="live-results-chart" label="Stored result counts sampled live" :points="samples" :series="liveSeries"/>
   </section>
   <div class="telemetry-grid">
    <section class="surface history-panel"><header class="section-heading"><div><span class="section-label">The longer view</span><h2>Daily scan history</h2><p class="helper">{{loadedDays}} days · grouped by creation date · UTC</p></div><q-btn flat dense :label="showTable?'Show chart':'View data'" @click="showTable=!showTable"/></header><div v-if="showTable" class="daily-table-scroll"><table class="resource-table"><thead><tr><th>UTC day</th><th>Created</th><th>Completed</th><th>Failed</th></tr></thead><tbody><tr v-for="d in overview.series" :key="d.day"><td>{{d.day}}</td><td>{{d.jobs}}</td><td>{{d.completed}}</td><td>{{d.failed}}</td></tr></tbody></table></div><div v-else class="history-chart"><SignalChart id="daily-history" label="Daily jobs created and their current outcomes, UTC" :points="history" :series="historySeries"/></div></section>
    <section class="surface capacity-panel"><header class="section-heading"><div><span class="section-label">Execution</span><h2>Runner capacity</h2></div><span class="capacity-count">{{online.length}} online</span></header><div class="capacity-body"><div class="capacity-number"><strong>{{busy}}</strong><span>/ {{slots}} slots</span><span class="capacity-percent">{{slots?Math.round(busy/slots*100):0}}% in use</span></div><div class="capacity-track" role="progressbar" aria-label="Occupied runner slots" :aria-valuenow="busy" :aria-valuemin="0" :aria-valuemax="Math.max(1,slots)"><span :style="{width:Math.min(100,slots?busy/slots*100:0)+'%'}"/></div><div v-if="!online.length" class="capacity-empty">No runners online.</div><div v-for="r in online" :key="r.id" class="runner-signal"><div class="runner-title"><i/><strong>{{r.name}}</strong><span>{{r.active_jobs}} / {{r.slots}}</span></div><dl class="runner-measures"><div><dt>Process CPU</dt><dd>{{cpu(r.cpu_percent)}}</dd></div><div><dt>Process RSS</dt><dd>{{bytes(r.rss_bytes)}}</dd></div></dl></div></div><q-btn flat dense label="All runners" :icon-right="matArrowForward" to="/runners"/></section>
    <section class="surface outcomes-panel" aria-label="All-time job outcomes"><header class="section-heading"><div><span class="section-label">Outcomes</span><h2>Where the work stands</h2></div><span class="helper">{{allJobs}} retained jobs</span></header><dl class="outcome-ledger"><div v-for="s in states" :key="s" :data-state="s"><dt>{{label(s)}}</dt><dd><span class="outcome-track"><i :style="{width:(allJobs?(overview.counts[s]??0)/allJobs*100:0)+'%'}"/></span><strong>{{overview.counts[s]??0}}</strong></dd></div></dl></section>
    <section class="surface recent-panel"><header class="section-heading"><div><span class="section-label">Activity</span><h2>Latest scans</h2></div><q-btn flat dense label="All jobs" :icon-right="matArrowForward" to="/jobs"/></header><div v-if="!overview.recent_jobs.length" class="recent-empty"><span class="empty-signal"/><h3>Ready for the next scan.</h3><p>Your scans will appear here as they run.</p><q-btn unelevated color="primary" text-color="dark" label="New scan" to="/jobs/new"/></div><a v-for="j in overview.recent_jobs.slice(0,5)" :key="j.id" class="recent-job" :href="'/jobs/'+encodeURIComponent(j.id)"><div><strong>{{j.name}}</strong><time :datetime="j.created_at">{{timestamp(j.created_at)}}</time></div><span class="status-badge" :data-state="j.state">{{label(j.state)}}</span></a></section>
   </div>
  </template>
 </q-page>
</template>
<style scoped>
.telemetry-workspace{max-width:1600px}.telemetry-controls{display:flex;align-items:center;gap:10px}.telemetry-controls .q-select{min-width:110px}.live-status{display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:650;white-space:nowrap}.live-status>i,.runner-title>i{width:7px;height:7px;border-radius:50%;background:#397459;box-shadow:0 0 0 4px #39745910}.live-status.disconnected>i{background:var(--muted);box-shadow:none}.live-interval{font:10px var(--mono);padding:3px 5px;border:1px solid var(--line);border-radius:4px;color:var(--muted)}.signal-board{padding:23px 26px 14px;background:var(--board);border:1px solid var(--board-line);border-radius:var(--radius);color:#f3f6f8;--chart-ink:#b7c5ce;--chart-strong:#f3f6f8;--chart-grid:#34424b;--chart-tooltip:#25323b;box-shadow:0 12px 28px -20px #17202670}.signal-top{display:flex;align-items:center;justify-content:space-between;gap:12px}.signal-top .section-label{color:var(--accent)}.signal-stamp{font:10px var(--mono);color:var(--board-muted)}.live-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:20px 0 26px}.live-metrics>div{padding:0 22px;border-left:1px solid var(--board-line)}.live-metrics>div:first-child{padding-left:0;border:0}.live-metrics dt{font-size:12px;color:var(--board-muted)}.live-metrics dd{margin:3px 0;font-size:clamp(30px,3.6vw,49px);line-height:1.25;letter-spacing:-.045em;font-weight:650;font-variant-numeric:tabular-nums;display:flex;align-items:center;gap:14px}.metric-primary dd{color:var(--accent)}.metric-context{font-size:10px;color:var(--board-muted)}.metric-marker{width:6px;height:6px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 5px #e8c83c15}.live-chart-heading{display:flex;align-items:center;justify-content:space-between;padding-top:18px;margin-bottom:12px;border-top:1px solid var(--board-line);gap:12px}.live-chart-heading h2{font-size:17px;font-weight:550;margin:0}.live-chart-heading>span{font:10px var(--mono);color:var(--board-muted)}.telemetry-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,1fr);gap:18px;margin-top:18px}.telemetry-grid>.surface{min-width:0;overflow:hidden}.section-heading{align-items:center;gap:12px;padding:19px 21px}.section-heading h2{font-size:18px;margin:6px 0 0}.section-heading .helper{font-size:10px;margin:7px 0 0}.section-label{font-size:10px}.history-chart{padding:8px 18px 16px}.daily-table-scroll{max-height:274px;overflow:auto}.capacity-count{font:11px var(--mono);white-space:nowrap}.capacity-body{padding:0 21px 12px;max-height:250px;overflow:auto}.capacity-number{display:flex;align-items:baseline;gap:8px;font-variant-numeric:tabular-nums}.capacity-number>strong{font-size:39px;line-height:1.2;font-weight:600;letter-spacing:-.04em}.capacity-number>span{font-size:12px;color:var(--muted)}.capacity-number .capacity-percent{margin-left:auto;font:10px var(--mono)}.capacity-track{height:7px;border-radius:4px;background:var(--canvas);margin:16px 0 20px;overflow:hidden}.capacity-track>span{display:block;height:100%;background:var(--ink);border-radius:4px;transition:width .25s ease-out}.runner-signal{border-top:1px solid var(--line);padding-top:13px;margin-top:12px}.runner-title{display:flex;align-items:center;gap:9px;font-size:11px}.runner-title>strong{font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.runner-title>span{margin-left:auto;font:10px var(--mono);color:var(--muted)}.runner-measures{display:flex;gap:25px;margin:14px 0 0}.runner-measures dt{font-size:10px;color:var(--muted)}.runner-measures dd{font:15px var(--mono);margin:3px 0 0}.capacity-panel>.q-btn{margin:0 16px 13px}.capacity-empty{font-size:12px;color:var(--muted);margin-bottom:12px}.outcome-ledger{margin:0;padding:0 21px 18px}.outcome-ledger>div{display:grid;grid-template-columns:100px minmax(0,1fr);align-items:center;gap:12px;padding:5px 0}.outcome-ledger dt{font-size:11px;text-transform:capitalize;color:var(--muted)}.outcome-ledger dd{display:flex;align-items:center;gap:15px;margin:0}.outcome-ledger strong{min-width:28px;text-align:right;font:12px var(--mono)}.outcome-track{height:5px;flex:1;border-radius:3px;overflow:hidden;background:var(--canvas)}.outcome-track>i{display:block;height:100%;background:var(--ink);transition:width .25s ease-out}.outcome-ledger [data-state=running] .outcome-track>i{background:#9b8114}.outcome-ledger [data-state=failed] .outcome-track>i{background:var(--danger)}.recent-job{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 21px;border-top:1px solid var(--line);text-decoration:none;transition:background .15s ease-out}.recent-job:hover{background:var(--canvas)}.recent-job>div{min-width:0}.recent-job strong{display:block;font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px}.recent-job time{font-size:10px;color:var(--muted)}.recent-job .status-badge{font-size:10px}.recent-empty{padding:15px 21px 25px}.recent-empty h3{font-size:18px;margin:17px 0 6px}.recent-empty p{font-size:12px;color:var(--muted);margin-bottom:15px}.empty-signal{display:block;width:34px;height:26px;border:1px solid var(--line);border-radius:5px;background:linear-gradient(transparent 47%,var(--line) 48%,var(--line) 52%,transparent 53%);position:relative}.empty-signal:after{content:'';position:absolute;width:5px;height:5px;border:1px solid var(--muted);background:var(--paper);border-radius:50%;top:9px;left:14px}.runner-sub{display:block;margin-top:5px;font-size:11px;color:var(--muted)}.capability{display:inline-block;font-size:11px;padding:3px 7px;background:var(--canvas);border-radius:4px;margin:2px 4px 2px 0}@media(max-width:1050px){.telemetry-grid{grid-template-columns:minmax(0,1.4fr) minmax(250px,1fr)}.live-metrics>div{padding:0 14px}.metric-context{font-size:9px}}@media(max-width:800px){.telemetry-grid{grid-template-columns:1fr}.live-metrics{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:18px}.live-metrics>div:nth-child(3){border:0;padding-left:0}.signal-board{padding:20px 18px 12px}.signal-stamp{font-size:9px}.live-chart-heading{align-items:baseline;flex-wrap:wrap}.recent-job strong{max-width:210px}}@media(max-width:480px){.telemetry-controls{gap:5px;flex-wrap:wrap}.telemetry-controls .q-select{min-width:100px}.live-status{font-size:11px}.signal-top{align-items:flex-start;flex-direction:column;gap:5px}.live-metrics dd{font-size:36px}.live-chart-heading>span{font-size:9px}.section-heading{padding:16px}.history-chart{padding:0 10px 12px}.outcome-ledger{padding:0 16px 16px}}@media(prefers-reduced-motion:reduce){.capacity-track>span,.outcome-track>i,.recent-job{transition:none}}
</style>
